#include "stdlib/stats/base/dists/kumaraswamy/logcdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/pow.h"
#include "stdlib/math/base/special/log1mexp.h"
#include "stdlib/math/base/special/log1p.h"
#include "stdlib/math/base/special/expm1.h"
#include "stdlib/math/base/special/ln.h"
#include "stdlib/constants/float64/ninf.h"
#include "stdlib/constants/float64/smallest_normal.h"

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a Kumaraswamy's double bounded distribution with first shape parameter `a` and second shape parameter `b` at a value `x`.
*
* @param x    input value
* @param a    first shape parameter
* @param b    second shape parameter
* @return     evaluated logCDF
*
* @example
* double y = stdlib_base_dists_kumaraswamy_logcdf( 0.5, 1.0, 1.0 );
* // returns ~-0.693
*/
double stdlib_base_dists_kumaraswamy_logcdf( const double x, const double a, const double b ) {
	double u;
	double v;
	double t;
	if (
		stdlib_base_is_nan( x ) ||
		stdlib_base_is_nan( a ) ||
		stdlib_base_is_nan( b ) ||
		a <= 0.0 ||
		b <= 0.0
	) {
		return 0.0/0.0; // NaN
	}
	if ( x <= 0.0 ) {
		return STDLIB_CONSTANT_FLOAT64_NINF;
	}
	if ( x >= 1.0 ) {
		return 0.0;
	}
	// Evaluate `v = ln(1-x^a)` without forming `1-x^a`, which rounds away the low-order bits of a small `x^a` and, for `x^a` close to `1`, of `1-x^a` itself:
	u = stdlib_base_pow( x, a );
	if ( u < STDLIB_CONSTANT_FLOAT64_SMALLEST_NORMAL ) {
		// `x^a` is subnormal or underflows, so `ln(1-(1-x^a)^b) = ln(b) + a*ln(x)`:
		return stdlib_base_ln( b ) + ( a * stdlib_base_ln( x ) );
	}
	if ( u < 0.5 ) {
		v = stdlib_base_log1p( -u );
	} else {
		v = stdlib_base_ln( -stdlib_base_expm1( a * stdlib_base_ln( x ) ) );
	}
	t = b * v;
	if ( t > -STDLIB_CONSTANT_FLOAT64_SMALLEST_NORMAL ) {
		return stdlib_base_ln( b ) + stdlib_base_ln( -v );
	}
	return stdlib_base_log1mexp( t );
}
